using System;using System.IO;using System.Linq;using System.Reflection;using System.Drawing;using System.Windows.Forms;using System.IO.Compression;using System.Collections.Generic;using System.Web.Script.Serialization;

// Offline only: no native engine, device factory, or real communication lease.
static class ReleaseTests {
 public static int Run(string project,string output){
  Directory.CreateDirectory(output);StudioUsbGate.UseTestLock(Path.Combine(output,"fixture-device.lock"));Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
  var cases=new List<object>();int failed=0;Action<bool> need=x=>{if(!x)throw new Exception("Assertion failed");};Action<string,Action> test=(name,body)=>{try{body();cases.Add(new{name=name,status="PASS"});}catch(Exception e){failed++;cases.Add(new{name=name,status="FAIL",error=e.ToString()});}};
  string hxf=Path.Combine(project,"build","POD_GO_NAM_Conr4d_v8.hxf");
  test("new_firmware_all17_checksums",()=>{var f=FirmwareFile.Read(hxf);need(f.Hash==PortableRuntime.CustomHash&&f.ImageCount==17&&!f.IsWithdrawn&&!f.IsOfficial);});
  test("exact_builtin_and_friedman_model_value_previews",()=>{need(NamTitle.Preview(0,"")=="0. Dev by Conr4d");need(NamTitle.Preview(53,"FRIEDMAN HBE")=="53. FRIEDMAN HBE");need(NamTitle.Preview(128,"FRIEDMAN HBE").Length==16);});
  test("both_languages_start_on_firmware_with_no_usb_or_sdk",()=>{foreach(string lang in new[]{"es","en"}){UiText.Select(lang);using(var w=new StudioWindow(false)){need(w.FirmwareVisible&&!w.InstallEnabled&&!w.IsBusy&&PortableRuntime.Root==null&&StudioUsbGate.Owner=="");need(Children(w).OfType<Label>().Any(c=>c.Text==(lang=="en"?"Firmware and recovery":"Firmware y recuperaci\u00f3n")));need(Children(w).OfType<StudioButton>().Single(c=>c.Name=="InterfaceLanguageEs").Marked==(lang=="es"));need(Children(w).OfType<StudioButton>().Single(c=>c.Name=="InterfaceLanguageEn").Marked==(lang=="en"));}}});
  test("backup_dialogs_are_translated_and_cancelable",()=>{foreach(string lang in new[]{"es","en"}){UiText.Select(lang);var cf=InstallNotice.For(new FirmwareFile());need(cf.Icon==MessageBoxIcon.Warning&&cf.Text.Contains(lang=="en"?"create a backup":"realiza un backup"));var stock=InstallNotice.For(new FirmwareFile{IsOfficial=true});need(stock.Icon==MessageBoxIcon.Information&&stock.Text.Contains("POD Go Edit"));}});
  test("embedded_cf_is_v8_and_stock_is_not_embedded",()=>{using(var input=Assembly.GetExecutingAssembly().GetManifestResourceStream("runtime.zip"))using(var z=new ZipArchive(input,ZipArchiveMode.Read)){need(!z.Entries.Any(e=>e.FullName.StartsWith("official/")));var cf=z.Entries.Single(e=>e.FullName.EndsWith(".hxf"));using(var s=cf.Open())using(var m=new MemoryStream()){s.CopyTo(m);need(FirmwareFile.Sha(m.ToArray())==PortableRuntime.CustomHash);}}});
  test("bilingual_offline_previews",()=>{string source=Path.Combine(project,"models","Developed by Conr4d.nam"),bank=Path.Combine(project,"tests","bank-preview.json");foreach(string lang in new[]{"es","en"}){UiText.Select(lang);using(var w=new StudioWindow(true,source,bank)){w.PrepareFirmwarePreview(hxf);w.Render(Path.Combine(output,"firmware-"+lang+".png"),true);w.Render(Path.Combine(output,"nam-"+lang+".png"),false,53);need(PortableRuntime.Root==null&&StudioUsbGate.Owner=="");}}});
  UiText.Select("es");File.WriteAllText(Path.Combine(output,"results.json"),new JavaScriptSerializer().Serialize(new{status=failed==0?"PASS_OFFLINE_ONLY":"FAIL",cases=cases,USB_opened=false,SDK_started=false,physical_display_verified=false}));return failed==0?0:1;
 }
 static IEnumerable<Control> Children(Control parent){foreach(Control c in parent.Controls){yield return c;foreach(var n in Children(c))yield return n;}}
}
